class Annotate( object ):
  def __init__( self , *args , **kwargs ):
    self.name = cmds.annotate( *args , **kwargs )

  def getpoint( self ):
    return cmds.annotate( self.name , q=1 , point=1 )
  def setpoint( self , value ):
    cmds.annotate( self.name , e=1 , point=value )
  point = property( getpoint , setpoint )

  def gettext( self ):
    return cmds.annotate( self.name , q=1 , text=1 )
  def settext( self , value ):
    cmds.annotate( self.name , e=1 , text=value )
  text = property( gettext , settext )






